      { schema: STAGE, phase: 'Review', label: 'review:#' + it.n })
  },
  (r, it) => {
    if (!r || !r.pr) return r
    return agent(`${PRE}

TASK (stage 3 of 4: simplify). PR #${r.pr} for issue #${it.n} on branch ${r.branch}; worktree ${r.worktree} (recreate if gone, as above). Run /simplify from the worktree, then commit and push what it applied (explicit paths); if it changed nothing, say so. The output is one step: continue after it. Return the stage result with the new head sha.`,
      { schema: STAGE, phase: 'Simplify', label: 'simplify:#' + it.n })
  },
  (r, it) => {
    if (!r || !r.pr) return r
    return agent(`${PRE}

TASK (stage 4 of 4: checks to READY). PR #${r.pr} for issue #${it.n} on branch ${r.branch}; worktree ${r.worktree}. Wait for every required check to complete on the FINAL head SHA of the PR branch (git fetch; gh pr view ${r.pr} --json headRefOid,statusCheckRollup). Wait in the FOREGROUND with blocking calls of at most ~10 minutes each (timeout 600 gh pr checks ${r.pr} --watch), repeated until all checks complete; never end your turn while checks are pending. If a check fails, read the log (gh run view --log-failed for that run only), fix with the smallest change, commit, push, and wait again on the new head. Do not regenerate baselines or change thresholds to pass. Do not merge. Return READY: pr, branch, sha (the PR's final head), checks as 'name: conclusion' for every check on that sha, needsRuling, notes (anything not green and why).`,
      { schema: STAGE, phase: 'Checks', label: 'checks:#' + it.n })
  },
)
return results

